-- ════════════════════════════════════════════════════════
-- 273 — Vague 2, suite : Cuba (sol, récolte, climat, variétés) et sept établissements
-- ────────────────────────────────────────────────────────
-- POURQUOI. Relus le 21 octobre 2026 sur pages lues (Cigar Aficionado, Habanos, Yacht Club
-- de Monaco). CUBA : « calcaire érodé et limons » sans page, retiré (reste « terres rouges »,
-- Vuelta Abajo) ; récolte précisée en cueillette, de janvier à mars ; « Tropical humide »
-- sans page, retiré ; liste `varieties` inchangée (ses étiquettes mènent aux fiches de feuille) ; `notes` précise,
-- datée de Cigar Aficionado 2000, que ce sont des hybrides de l'ancien Corojo (Habano 2000,
-- Criollo 98, Corojo 99). ÉTABLISSEMENTS : nom et
-- description corrigés pour Hanoi (141, Angelina, Habanos Lounge ; Habanos le date d'avril
-- 2025, un communiqué relayé d'août 2024), Hotel Nacional (1564, bar à cigares à l'étage,
-- ouvert en 2022) et Yacht Club de Monaco (1614, Hemingway Cigar Lounge, membres et invités) ;
-- dépubliés, réversibles : Raffles (1463, source de 1993), One°15 (1464) et Alvear (2524,
-- fermé selon une chronique de 2015). Churchill Bar (280) reste publié : pages Hyatt illisibles,
-- à revérifier.
-- ════════════════════════════════════════════════════════

-- ── Cuba ──
UPDATE `producer_countries` SET `soil` = 'Terres rouges (Vuelta Abajo)', `soil_en` = 'Red soils (Vuelta Abajo)', `soil_es` = 'Tierras rojas (Vuelta Abajo)', `soil_de` = 'Rote Böden (Vuelta Abajo)', `soil_zh` = '红土（Vuelta Abajo）', `soil_ar` = 'تربة حمراء (فويلتا أباخو)' WHERE `id` = 'cuba';
UPDATE `producer_countries` SET `harvest` = 'Cueillette : de janvier à mars', `harvest_en` = 'Harvest: January to March', `harvest_es` = 'Cosecha: de enero a marzo', `harvest_de` = 'Ernte: Januar bis März', `harvest_zh` = '采收期：1月至3月', `harvest_ar` = 'الحصاد: من يناير إلى مارس' WHERE `id` = 'cuba';
UPDATE `producer_countries` SET `climate` = NULL, `climate_en` = NULL, `climate_es` = NULL, `climate_de` = NULL, `climate_zh` = NULL, `climate_ar` = NULL WHERE `id` = 'cuba';
UPDATE `producer_countries` SET `notes` = CONCAT(`notes`, ' Variétés citées par Cigar Aficionado en 2000 : Habano 2000, Criollo 98 et Corojo 99, hybrides de l''ancien Corojo, disparu vers 1997.'), `notes_en` = CONCAT(`notes_en`, ' Varieties cited by Cigar Aficionado in 2000: Habano 2000, Criollo 98 and Corojo 99, hybrids of the old Corojo, which disappeared around 1997.'), `notes_es` = CONCAT(`notes_es`, ' Variedades citadas por Cigar Aficionado en 2000: Habano 2000, Criollo 98 y Corojo 99, híbridos del antiguo Corojo, desaparecido hacia 1997.'), `notes_de` = CONCAT(`notes_de`, ' Von Cigar Aficionado im Jahr 2000 genannte Sorten: Habano 2000, Criollo 98 und Corojo 99, Hybriden des alten Corojo, der um 1997 verschwand.'), `notes_zh` = CONCAT(`notes_zh`, ' 《Cigar Aficionado》在2000年提到的品种有：Habano 2000、Criollo 98和Corojo 99，它们是旧Corojo的杂交品种，而旧Corojo约在1997年消失。'), `notes_ar` = CONCAT(`notes_ar`, ' الأصناف التي ذكرتها مجلة Cigar Aficionado في عام 2000: Habano 2000 وCriollo 98 وCorojo 99، وهي هجائن من الكوروخو القديم الذي اختفى نحو عام 1997.') WHERE `id` = 'cuba';
DELETE FROM `translation_status` WHERE `entite` = 'producer_countries' AND `entite_id` = 'cuba' AND `champ` = 'climate';
UPDATE `translation_status` t JOIN `producer_countries` p ON p.`id` = t.`entite_id` AND t.`entite` = 'producer_countries'
   SET t.`source_hash` = SHA1(CASE t.`champ` WHEN 'soil' THEN p.`soil` WHEN 'harvest' THEN p.`harvest` WHEN 'notes' THEN p.`notes` END), t.`maj` = NOW()
 WHERE p.`id` = 'cuba' AND t.`champ` IN ('soil','harvest','notes');

-- ── Établissements corrigés ──
UPDATE `lounges` SET `name` = 'Sofitel Legend Metropole Hanoi — Angelina (Habanos Lounge)', `description` = 'Angelina, salon whisky et restaurant du Sofitel Legend Metropole Hanoi, a été reconnu « Habanos Lounge » ; Habanos le présente comme le premier de la capitale vietnamienne. Son humidor réunit des marques Habanos dont Cohiba, Montecristo, Romeo y Julieta, Partagás, Hoyo de Monterrey et H. Upmann.', `description_en` = 'Angelina, the whisky lounge and restaurant of the Sofitel Legend Metropole Hanoi, has been recognized as a "Habanos Lounge"; Habanos presents it as the first in the Vietnamese capital. Its humidor holds Habanos brands including Cohiba, Montecristo, Romeo y Julieta, Partagás, Hoyo de Monterrey and H. Upmann.', `description_es` = 'Angelina, el salón de whisky y restaurante del Sofitel Legend Metropole Hanoi, ha sido reconocido como «Habanos Lounge»; Habanos lo presenta como el primero de la capital vietnamita. Su humidor reúne marcas Habanos, entre ellas Cohiba, Montecristo, Romeo y Julieta, Partagás, Hoyo de Monterrey y H. Upmann.', `description_de` = 'Angelina, die Whisky-Lounge und das Restaurant des Sofitel Legend Metropole Hanoi, wurde als „Habanos Lounge“ anerkannt; Habanos bezeichnet sie als die erste in der vietnamesischen Hauptstadt. Der Humidor enthält Habanos-Marken, darunter Cohiba, Montecristo, Romeo y Julieta, Partagás, Hoyo de Monterrey und H. Upmann.', `description_zh` = '河内索菲特传奇大都会酒店（Sofitel Legend Metropole Hanoi）的威士忌酒廊兼餐厅Angelina被认定为“Habanos Lounge”；Habanos称其为越南首都的第一家。其雪茄保湿盒中收藏有多个Habanos品牌，包括Cohiba、Montecristo、Romeo y Julieta、Partagás、Hoyo de Monterrey和H. Upmann。', `description_ar` = 'تم اعتماد «أنجلينا»، صالون الويسكي والمطعم في فندق Sofitel Legend Metropole Hanoi، بوصفه «Habanos Lounge»؛ وتقدّمه Habanos على أنه الأول في العاصمة الفيتنامية. ويضم الهيوميدور فيه علامات Habanos، من بينها Cohiba وMontecristo وRomeo y Julieta وPartagás وHoyo de Monterrey وH. Upmann.', `source` = 'habanos.com (page du 3 avril 2025, lue le 21 octobre 2026) ; communiqué d''août 2024 relayé par journaldespalaces.com : la date diverge', `updated_at` = NOW()
 WHERE `id` = 141 AND `country_id` = 'vietnam';
UPDATE `lounges` SET `name` = 'Hotel Nacional de Cuba — bar à cigares à l''étage', `description` = 'Au Hotel Nacional de Cuba, Cigar Aficionado (numéro Cuba, mai/juin 2024) décrit un bar à cigares discret à l''étage, accessible par un petit escalier, ouvert en 2022 et dirigé par Yanset Torres, Habanosommelier formé. La Casa del Habano de l''hôtel se trouve en dessous. Terrasse avec vue sur la mer d''un côté, sur la façade de l''hôtel de l''autre.', `description_en` = 'At the Hotel Nacional de Cuba, Cigar Aficionado (Cuba issue, May/June 2024) describes a discreet cigar bar upstairs, reached by a small staircase, opened in 2022 and run by Yanset Torres, a trained Habanosommelier. The hotel''s Casa del Habano is located below. Terrace with a view of the sea on one side and of the hotel facade on the other.', `description_es` = 'En el Hotel Nacional de Cuba, Cigar Aficionado (número dedicado a Cuba, mayo/junio de 2024) describe un bar de cigarros discreto en la planta superior, al que se accede por una pequeña escalera, abierto en 2022 y dirigido por Yanset Torres, Habanosommelier titulado. La Casa del Habano del hotel se encuentra debajo. Terraza con vistas al mar por un lado y a la fachada del hotel por el otro.', `description_de` = 'Im Hotel Nacional de Cuba beschreibt Cigar Aficionado (Kuba-Ausgabe, Mai/Juni 2024) eine diskrete Zigarrenbar im Obergeschoss, über eine kleine Treppe erreichbar, 2022 eröffnet und geleitet von Yanset Torres, einem ausgebildeten Habanosommelier. Die Casa del Habano des Hotels befindet sich darunter. Terrasse mit Blick auf das Meer auf der einen und auf die Hotelfassade auf der anderen Seite.', `description_zh` = '在古巴国家酒店（Hotel Nacional de Cuba），《Cigar Aficionado》（古巴专号，2024年5/6月）描述楼上有一间低调的雪茄吧，需通过一段小楼梯到达，2022年开业，由受过培训的Habanosommelier Yanset Torres负责。酒店的Casa del Habano就在其下方。露台一侧可眺望大海，另一侧面向酒店外立面。', `description_ar` = 'في فندق Hotel Nacional de Cuba، تصف مجلة Cigar Aficionado (عدد كوبا، مايو/يونيو 2024) حانة سيجار هادئة في الطابق العلوي، يُصعد إليها عبر درج صغير، افتُتحت في عام 2022 ويديرها يانسيت توريس، وهو Habanosommelier مؤهَّل. ويقع Casa del Habano التابع للفندق أسفلها. شرفة تطل على البحر من جهة وعلى واجهة الفندق من الجهة الأخرى.', `source` = 'cigaraficionado.com (numéro mai/juin 2024, lu le 21 octobre 2026) ; état actuel non attesté', `updated_at` = NOW()
 WHERE `id` = 1564 AND `country_id` = 'cuba';
UPDATE `lounges` SET `name` = 'Yacht Club de Monaco — Hemingway Cigar Lounge', `description` = 'Le Hemingway Cigar Lounge du Yacht Club de Monaco, entièrement redessiné par Andrea Zanetti et inauguré le 20 mai 2026, est réservé aux membres du club et à leurs invités. Il compte 87 casiers privés et ouvre sur une terrasse avec vue sur la marina du YCM et le Rocher.', `description_en` = 'The Hemingway Cigar Lounge of the Yacht Club de Monaco, entirely redesigned by Andrea Zanetti and inaugurated on 20 May 2026, is reserved for club members and their guests. It has 87 private lockers and opens onto a terrace overlooking the YCM marina and the Rock.', `description_es` = 'El Hemingway Cigar Lounge del Yacht Club de Monaco, completamente rediseñado por Andrea Zanetti e inaugurado el 20 de mayo de 2026, está reservado a los socios del club y a sus invitados. Cuenta con 87 taquillas privadas y da a una terraza con vistas a la marina del YCM y al Peñón.', `description_de` = 'Die Hemingway Cigar Lounge des Yacht Club de Monaco, vollständig von Andrea Zanetti neu gestaltet und am 20. Mai 2026 eingeweiht, ist den Clubmitgliedern und ihren Gästen vorbehalten. Sie verfügt über 87 private Fächer und öffnet sich auf eine Terrasse mit Blick auf den Hafen des YCM und den Felsen.', `description_zh` = '摩纳哥游艇俱乐部（Yacht Club de Monaco）的Hemingway Cigar Lounge由Andrea Zanetti全面重新设计，于2026年5月20日启用，仅限俱乐部会员及其宾客使用。这里设有87个私人储物柜，并通向一处露台，可眺望YCM码头和摩纳哥岩。', `description_ar` = 'صالون Hemingway Cigar Lounge في Yacht Club de Monaco، الذي أعاد تصميمه بالكامل Andrea Zanetti وافتُتح في 20 مايو 2026، مخصص لأعضاء النادي وضيوفهم. ويضم 87 خزانة خاصة ويطل على شرفة تُشرف على مرفأ YCM والصخرة.', `source` = 'yacht-club-monaco.mc (21 mai 2026, lu le 21 octobre 2026)', `updated_at` = NOW()
 WHERE `id` = 1614 AND `country_id` = 'monaco';
UPDATE `translation_status` t JOIN `lounges` l ON l.`id` = t.`entite_id` AND t.`entite` = 'lounges' AND t.`champ` = 'description'
   SET t.`source_hash` = SHA1(l.`description`), t.`maj` = NOW()
 WHERE l.`id` IN (141, 1564, 1614);

-- ── Établissements dépubliés ──
UPDATE `lounges` SET `is_verified` = 0, `source` = 'RETIRÉ — relu le 21 octobre 2026 : aucune page de l''hôtel n''atteste aujourd''hui des cigares à la Bar & Billiard Room ; seule source lue : Cigar Aficionado, hiver 1993/94 ; à rétablir si une page est apportée', `updated_at` = NOW()
 WHERE `id` = 1463 AND `country_id` = 'singapore';
UPDATE `lounges` SET `is_verified` = 0, `source` = 'RETIRÉ — relu le 21 octobre 2026 : aucune page n''atteste un lounge ou un humidor ; seule mention : des cigares au Bar Nebula en 2007 ; à rétablir si une page est apportée', `updated_at` = NOW()
 WHERE `id` = 1464 AND `country_id` = 'singapore';
UPDATE `lounges` SET `is_verified` = 0, `source` = 'RETIRÉ — relu le 21 octobre 2026 : une chronique de février 2015 dit que l''hôtel a fermé son Cigar Bar ; aucune page de l''hôtel ne l''atteste aujourd''hui ; à rétablir si une page est apportée', `updated_at` = NOW()
 WHERE `id` = 2524 AND `country_id` = 'argentina';

-- ── Contrôle ──
SELECT (SELECT COUNT(*) FROM `lounges` WHERE `id` IN (141,1564,1614) AND `is_verified` = 1) AS trois_corrigees_publiees,
       (SELECT COUNT(*) FROM `lounges` WHERE `id` IN (1463,1464,2524) AND `is_verified` = 0) AS trois_depubliees,
       (SELECT COUNT(*) FROM `producer_countries` WHERE `id` = 'cuba' AND `climate` IS NULL AND `notes` LIKE '%Corojo 99%') AS cuba_ok;
